    BOOLEAN is_fat32;
    UINT8   sec_per_cluster;
    UINT16  reserved_secs;
    UINT8   num_fats;
    UINT16  root_entries;
    UINT32  secs_per_fat;
    UINT32  eoc_cluster;
    UINT32  root_cluster;
    UINT32  root_dir_start;
    UINT32  root_dir_sectors;
    UINT32  data_start;
    UINT32  cluster_size;
