UINTN fw_partition_count(VOID)
{
    UINTN count = 0;
    UINTN index;

    for (index = 0; index < FW_ARRAY_SIZE(mPartitions); index++) {
        if (mPartitions[index].in_use) {
            count++;
        }
    }
    return count;
}

